import { Column, CreateDateColumn, Entity, Index, PrimaryColumn, Unique } from 'typeorm';

/** A run waiting for a command-button press on one outgoing messenger message. */
@Entity('button_waits')
@Unique('UQ_button_waits_message', ['projectId', 'env', 'vendor', 'credentialId', 'chatId', 'messageId'])
@Index('IDX_button_waits_expires', ['expiresAt'])
export class ButtonWait {
  /** `<runId>:<activityId>` — generated by the asking activity before it sends the callback buttons. */
  @PrimaryColumn({ type: 'varchar' })
  id!: string;

  @Column({ name: 'project_id', type: 'uuid' })
  projectId!: string;

  @Column({ type: 'varchar' })
  env!: 'dev' | 'prod';

  @Column({ type: 'varchar' })
  vendor!: string;

  @Column({ name: 'credential_id', type: 'varchar' })
  credentialId!: string;

  @Column({ name: 'chat_id', type: 'varchar' })
  chatId!: string;

  @Column({ name: 'message_id', type: 'varchar' })
  messageId!: string;

  @Column({ name: 'workflow_id', type: 'varchar' })
  workflowId!: string;

  @Column({ name: 'run_id', type: 'varchar' })
  runId!: string;

  @Column({ name: 'expires_at', type: Date })
  expiresAt!: Date;

  @CreateDateColumn({ name: 'created_at', type: Date })
  createdAt!: Date;
}
